        int minInts;
        int maxFracs;
        if (Format.length() == 0) {
            return BA.ObjectToString(Value);
        }
        if (Format.equals("date")) {
            return DateTime.Date(BA.ObjectToLongNumber(Value));
        }
        if (Format.equals("datetime")) {
