            File file = Common.File;
            File.InputStreamWrapper in = File.OpenInput(Dir, FileName);
            BitmapFactory.Options o = new BitmapFactory.Options();
            o.inJustDecodeBounds = true;
            BitmapFactory.decodeStream(in.getObject(), null, o);
