        cutcanvas.drawBitmap(bitmap, rect, tgtR, new Paint(2));
        float ratioX = newWidth / cutbitmap.getWidth();
        float ratioY = newHeight / cutbitmap.getHeight();
        float middleX = newWidth / 2.0f;
        float middleY = newHeight / 2.0f;
        Matrix scaleMatrix = new Matrix();
        scaleMatrix.setScale(ratioX, ratioY, middleX, middleY);
        Canvas canvas = new Canvas(scaledBitmap);
        canvas.setMatrix(scaleMatrix);
        canvas.drawBitmap(cutbitmap, middleX - (cutbitmap.getWidth() / 2), middleY - (cutbitmap.getHeight() / 2), new Paint(2));
        return scaledBitmap;
    }

