    public Bitmap Blur(Bitmap bmp, float Level, int Speed) {
        int L = (int) (Level - Math.round(Level * 0.4d));
        switch (Speed) {
            case 0:
                Bitmap p = Resize(bmp, 50.0f);
                return InnerBlur(Resize(InnerBlur(p, L), 200.0f), 1.0f);
            case 1:
                Bitmap p2 = Resize(bmp, 25.0f);
                return InnerBlur(Resize(InnerBlur(p2, L), 400.0f), 1.0f);
            default:
                return null;
        }
    }

    private Bitmap InnerBlur(Bitmap bmp, float Level) {
        int w = bmp.getWidth();
        int h = bmp.getHeight();
        Paint paint = new Paint();
        paint.setAlpha(127);
        Bitmap t = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        Canvas tc = new Canvas(t);
        Bitmap p = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888);
        Canvas pc = new Canvas(p);
        pc.drawBitmap(bmp, Common.Density, Common.Density, (Paint) null);
        int Lev = (int) Level;
        for (int L = Lev; L > 0; L--) {
            tc.drawBitmap(p, Common.Density, Common.Density, paint);
            pc.drawBitmap(t, -L, -L, (Paint) null);
            tc.drawBitmap(p, Common.Density, Common.Density, paint);
            pc.drawBitmap(t, -L, L, (Paint) null);
            tc.drawBitmap(p, Common.Density, Common.Density, paint);
            pc.drawBitmap(t, L, L, (Paint) null);
            tc.drawBitmap(p, Common.Density, Common.Density, paint);
            pc.drawBitmap(t, L, -L, (Paint) null);
        }
        t.recycle();
        return p;
    }

    public Bitmap Resize(Bitmap bmp, float Percentage) {
        float by = (float) (Percentage / 100.0d);
        int w = (int) (bmp.getWidth() * by);
        int h = (int) (bmp.getHeight() * by);
        return Percentage > 100.0f ? Bitmap.createScaledBitmap(bmp, w, h, true) : Bitmap.createScaledBitmap(bmp, w, h, false);
    }

    public Bitmap Saturate(Bitmap bmp, float Ammount) {
        ColorMatrix colorMatrix = new ColorMatrix();
        ColorMatrixColorFilter cmFilter = new ColorMatrixColorFilter(colorMatrix);
        Paint cmPaint = new Paint();
        cmPaint.setColorFilter(cmFilter);
        colorMatrix.setSaturation(Ammount / 100.0f);
        ColorMatrixColorFilter cmFilter2 = new ColorMatrixColorFilter(colorMatrix);
        cmPaint.setColorFilter(cmFilter2);
        Bitmap alteredBitmap = Bitmap.createBitmap(bmp.getWidth(), bmp.getHeight(), bmp.getConfig());
        Canvas canvas = new Canvas(alteredBitmap);
        canvas.drawBitmap(bmp, Common.Density, Common.Density, cmPaint);
        return alteredBitmap;
    }

