    public static class ABRgbFunctions {
        public static int toRgb(byte R, byte G, byte B) {
            return (-16777216) | (toUnsignedInt(R) << 16) | (toUnsignedInt(G) << 8) | toUnsignedInt(B);
        }

        public static int getAbsDiff(int rgb1, int rgb2) {
            return Math.abs(getR(rgb1) - getR(rgb2)) + Math.abs(getG(rgb1) - getG(rgb2)) + Math.abs(getB(rgb1) - getB(rgb2));
        }

        public static int getMaxDiff(int ARGB1, int ARGB2) {
            int nR1 = getR(ARGB1);
            int nG1 = getG(ARGB1);
            int nB1 = getB(ARGB1);
            int nR2 = getR(ARGB2);
            int nG2 = getG(ARGB2);
            int nB2 = getB(ARGB2);
            return Math.max(Math.abs(nR1 - nR2), Math.max(Math.abs(nG1 - nG2), Math.abs(nB1 - nB2)));
        }

        public static int getProportionateDiff(int ARGB1, int ARGB2) {
            int nR1 = getR(ARGB1) + 128;
            int nG1 = getG(ARGB1) + 128;
            int nB1 = getB(ARGB1) + 128;
            int nR2 = getR(ARGB2) + 128;
            int nG2 = getG(ARGB2) + 128;
            int nB2 = getB(ARGB2) + 128;
            int nNum = (nR1 * nR2) + (nG1 * nG2) + (nB1 * nB2);
            int nDenom = (nR1 * nR1) + (nG1 * nG1) + (nB1 * nB1);
            if (nDenom == 0) {
                return 381;
            }
            return square(((((nR1 + nG1) + nB1) * nNum) - (((nR1 + nG2) + nB2) * nDenom)) * 8) / square(nDenom);
        }

        public static int getSqrDiff(int rgb1, int rgb2) {
            return square(getR(rgb1) - getR(rgb2)) + square(getG(rgb1) - getG(rgb2)) + square(getB(rgb1) - getB(rgb2));
        }

        public static byte getB(int ARGB) {
            return toSignedByte((byte) (ARGB & 255));
        }

        public static byte getG(int ARGB) {
            return toSignedByte((byte) ((ARGB >> 8) & 255));
        }

        public static byte getR(int ARGB) {
            return toSignedByte((byte) ((ARGB >> 16) & 255));
        }

        public static int getVecDiff(int ARGB, int ARGBTarg, int ARGBVec) {
            int nR1 = getR(ARGB);
            int nG1 = getG(ARGB);
            int nB1 = getB(ARGB);
            int nR2 = getR(ARGBTarg);
            int nG2 = getG(ARGBTarg);
            int nB2 = getB(ARGBTarg);
            int nR3 = getR(ARGBVec);
            int nG3 = getG(ARGBVec);
            int nB3 = getB(ARGBVec);
            return ((nR1 - nR2) * nR3) + ((nG1 - nG2) * nG3) + ((nB1 - nB2) * nB3);
        }

        public static byte toSignedByte(byte b) {
            return (byte) (b - 128);
        }

        public static int toUnsignedInt(byte b) {
            return b + 128;
        }

        public static String toString(int ARGB) {
            return "[" + new Integer(getR(ARGB)).toString() + "," + new Integer(getR(ARGB)).toString() + "," + new Integer(getB(ARGB)).toString() + "]";
        }

        protected static int square(int n) {
            return n * n;
        }
    }

